Biographics Legacy outro with typewriter effect. 16 seconds, 1920x1080, SILENT. No red boxes, no CTA bar, no pill buttons — pure typography over video.

```html
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<link href="https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,700;1,400;1,700&display=swap" rel="stylesheet">
<style>
*{margin:0;padding:0;box-sizing:border-box;}
body,#scene{width:1920px;height:1080px;overflow:hidden;background:#000;}
#scene{position:relative;display:flex;align-items:center;justify-content:center;}

#bg{position:absolute;top:0;left:0;width:100%;height:100%;object-fit:cover;z-index:1;opacity:0;}
#overlay{position:absolute;top:0;left:0;width:100%;height:100%;z-index:2;
  background:linear-gradient(to top,rgba(0,0,0,0.88) 0%,rgba(0,0,0,0.40) 55%,rgba(0,0,0,0.20) 100%);}
#fade{position:absolute;top:0;left:0;width:100%;height:100%;z-index:50;background:#000;opacity:0;pointer-events:none;}

/* center content block */
#content{
  position:relative;z-index:10;
  display:flex;flex-direction:column;align-items:center;
  gap:0;
  width:1400px;
}

/* top maroon rule */
#rule-top{
  width:0;height:1px;
  background:linear-gradient(to right,transparent,#8b2e2e 20%,#8b2e2e 80%,transparent);
  margin-bottom:36px;
}

/* outro line 1 */
#line1{
  font-family:'Playfair Display',Georgia,serif;
  font-size:34px;font-style:italic;font-weight:400;
  color:rgba(220,208,192,0.90);letter-spacing:0.04em;
  text-align:center;line-height:1.4;
  overflow:hidden;white-space:nowrap;width:0;
}

/* outro line 2 */
#line2{
  font-family:'Playfair Display',Georgia,serif;
  font-size:34px;font-style:italic;font-weight:400;
  color:rgba(220,208,192,0.90);letter-spacing:0.04em;
  text-align:center;line-height:1.4;margin-top:4px;
  overflow:hidden;white-space:nowrap;width:0;
}

/* bottom rule */
#rule-bot{
  width:0;height:1px;
  background:linear-gradient(to right,transparent,#8b2e2e 20%,#8b2e2e 80%,transparent);
  margin-top:36px;margin-bottom:52px;
}

/* history line — separated lower */
#history{
  font-family:'Playfair Display',Georgia,serif;
  font-size:22px;font-weight:700;
  color:#8b2e2e;letter-spacing:0.38em;text-transform:uppercase;
  text-align:center;
  overflow:hidden;white-space:nowrap;width:0;
}

/* subscribe hint — very subtle, below history */
#sub-hint{
  margin-top:32px;
  font-family:'Playfair Display',Georgia,serif;
  font-size:15px;font-style:italic;
  color:rgba(200,185,165,0.55);letter-spacing:0.16em;
  text-align:center;
  opacity:0;
}
</style>
</head>
<body>
<div id="scene">
  <video id="bg" autoplay muted loop playsinline>
    <source src="{{bgVid}}" type="video/mp4">
  </video>
  <div id="overlay"></div>
  <div id="fade"></div>

  <div id="content">
    <div id="rule-top"></div>
    <div id="line1">From London fog to Strange dimensions —</div>
    <div id="line2">and back to the stage where it began.</div>
    <div id="rule-bot"></div>
    <div id="history">History, one life at a time.</div>
    <div id="sub-hint">Subscribe for more Biographies</div>
  </div>
</div>

<script src="vendor/gsap.min.js"></script>
<script>
window.addEventListener('DOMContentLoaded', function(){

  // measure full widths before animating
  var w1 = document.getElementById('line1').scrollWidth;
  var w2 = document.getElementById('line2').scrollWidth;
  var wh = document.getElementById('history').scrollWidth;
  var wr = 560; // rule width

  var tl = gsap.timeline();

  // bg fade in
  tl.to('#bg', {opacity:0.50, duration:1.0, ease:'power2.out'}, 0);

  // top rule draws in
  tl.to('#rule-top', {width:wr, duration:0.5, ease:'power2.out'}, 0.8);

  // line 1 — typewriter: width expands from 0 to full
  tl.to('#line1', {width:w1, duration:1.6, ease:'none'}, 1.5);

  // line 2 — typewriter after line 1
  tl.to('#line2', {width:w2, duration:1.4, ease:'none'}, 3.3);

  // bottom rule draws in
  tl.to('#rule-bot', {width:wr, duration:0.5, ease:'power2.out'}, 5.0);

  // history line — typewriter
  tl.to('#history', {width:wh, duration:1.4, ease:'none'}, 5.8);

  // subscribe hint fades in subtly
  tl.to('#sub-hint', {opacity:1, duration:0.8, ease:'power2.out'}, 8.0);

  // --- exit sequence ---
  // sub-hint fades out first
  tl.to('#sub-hint', {opacity:0, duration:0.5, ease:'power2.in'}, 11.5);

  // history erases (typewriter reverse: width back to 0)
  tl.to('#history', {width:0, duration:0.8, ease:'none'}, 11.8);

  // rules retract
  tl.to(['#rule-top','#rule-bot'], {width:0, duration:0.4, ease:'power2.in'}, 12.2);

  // lines erase simultaneously
  tl.to(['#line1','#line2'], {width:0, duration:0.7, ease:'none'}, 12.3);

  // fade to black
  tl.to('#fade', {opacity:1, duration:1.8, ease:'power2.inOut'}, 13.8);
});
</script>
</body>
</html>
```
